import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const USE_STATUSES = ['사용', '미사용'];
const INPUT_INVALID = 'SUB_PROJECT_INPUT_INVALID';

function toId(v: unknown): number | null {
  const n = typeof v === 'string' && v.trim() !== '' ? Number(v) : v;
  if (typeof n === 'number' && Number.isInteger(n) && n > 0) {
    return n;
  }
  return null;
}

function text(v: unknown, max: number, required: boolean): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) {
      throw new ApiError(422, INPUT_INVALID, '필수 값이 누락되었습니다.');
    }
    return null;
  }
  if (typeof v !== 'string' || v.length > max) {
    throw new ApiError(422, INPUT_INVALID, '입력 형식이 올바르지 않습니다.');
  }
  return v;
}

function employeeIds(v: unknown): number[] | undefined {
  if (v === undefined || v === null) {
    return undefined;
  }
  if (!Array.isArray(v)) {
    throw new ApiError(422, INPUT_INVALID, '사용 권한 대상 형식이 올바르지 않습니다.');
  }
  const ids: number[] = [];
  for (const item of v) {
    const id = toId(item);
    if (id === null) {
      throw new ApiError(422, INPUT_INVALID, '사용 권한 대상 임직원 ID가 올바르지 않습니다.');
    }
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids;
}

interface Fields {
  code: string;
  name: string;
  account: string | null;
  useStatus: string;
  parentId: number | null;
  permitted: number[] | undefined;
}

function readFields(data: Record<string, unknown>): Fields {
  const code = text(data['subProjectCode'], 30, true) as string;
  const name = text(data['subProjectName'], 200, true) as string;
  const account = text(data['managingAccount'], 50, false);
  const useStatus = data['useStatus'];
  if (typeof useStatus !== 'string' || !USE_STATUSES.includes(useStatus)) {
    throw new ApiError(422, INPUT_INVALID, '사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  let parentId: number | null = null;
  const rawParent = data['parentSubProjectId'];
  if (rawParent !== undefined && rawParent !== null && rawParent !== '') {
    parentId = toId(rawParent);
    if (parentId === null) {
      throw new ApiError(422, INPUT_INVALID, '상위 하위사업 ID가 올바르지 않습니다.');
    }
  }
  return { code, name, account, useStatus, parentId, permitted: employeeIds(data['permittedEmployeeIds']) };
}

@Controller('api/v1')
export class FnSfr00202Controller {
  @Post('/sub-projects')
  @HttpCode(200)
  async createSubProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const projectId = toId(data['projectId']);
    if (projectId === null) {
      throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 지정해 주세요.');
    }
    const f = readFields(data);
    return transaction(async (db) => {
      const projects = await db.query(
        `SELECT project_id AS "projectId" FROM project WHERE project_id = CAST(:projectId AS bigint)`,
        { projectId },
      );
      if (projects.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      if (f.parentId !== null) {
        const parents = await db.query(
          `SELECT project_id AS "projectId" FROM sub_project WHERE sub_project_id = CAST(:parentId AS bigint)`,
          { parentId: f.parentId },
        );
        if (parents.length === 0 || Number(parents[0]['projectId']) !== projectId) {
          throw new ApiError(422, INPUT_INVALID, '상위 하위사업이 없거나 같은 프로젝트 소속이 아닙니다.');
        }
      }
      const dup = await db.query(
        `SELECT sub_project_id AS "subProjectId" FROM sub_project WHERE project_id = CAST(:projectId AS bigint) AND sub_project_code = :code`,
        { projectId, code: f.code },
      );
      if (dup.length > 0) {
        throw new ApiError(422, INPUT_INVALID, '프로젝트 안에 같은 하위사업 코드가 있습니다.');
      }
      await checkEmployees(db, f.permitted);
      const rows = await db.query(
        `INSERT INTO sub_project (project_id, parent_sub_project_id, sub_project_code, sub_project_name, managing_account, use_status, created_at, updated_at)
         VALUES (CAST(:projectId AS bigint), CAST(:parentId AS bigint), :code, :name, :account, :useStatus, now(), now())
         RETURNING sub_project_id AS "subProjectId"`,
        { projectId, parentId: f.parentId, code: f.code, name: f.name, account: f.account, useStatus: f.useStatus },
      );
      const subProjectId = Number(rows[0]['subProjectId']);
      await savePermissions(db, projectId, subProjectId, f.permitted);
      return { subProjectId };
    });
  }

  @Put('/sub-projects/:subProjectId')
  @HttpCode(200)
  async updateSubProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const subProjectId = toId(req.params['subProjectId']);
    if (subProjectId === null) {
      throw new ApiError(404, 'SUB_PROJECT_NOT_FOUND', '하위사업을 찾을 수 없습니다.');
    }
    const data = checks.inputOf(req.body);
    const f = readFields(data);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT project_id AS "projectId" FROM sub_project WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
        { subProjectId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SUB_PROJECT_NOT_FOUND', '하위사업을 찾을 수 없습니다.');
      }
      const projectId = Number(found[0]['projectId']);
      if (f.parentId !== null) {
        const parents = await db.query(
          `SELECT project_id AS "projectId" FROM sub_project WHERE sub_project_id = CAST(:parentId AS bigint)`,
          { parentId: f.parentId },
        );
        if (parents.length === 0 || Number(parents[0]['projectId']) !== projectId) {
          throw new ApiError(422, INPUT_INVALID, '상위 하위사업이 없거나 같은 프로젝트 소속이 아닙니다.');
        }
        const cycle = await db.query(
          `WITH RECURSIVE sub AS (
             SELECT sub_project_id FROM sub_project WHERE sub_project_id = CAST(:subProjectId AS bigint)
             UNION ALL
             SELECT c.sub_project_id FROM sub_project c JOIN sub s ON c.parent_sub_project_id = s.sub_project_id
           )
           SELECT sub_project_id AS "subProjectId" FROM sub WHERE sub_project_id = CAST(:parentId AS bigint)`,
          { subProjectId, parentId: f.parentId },
        );
        if (cycle.length > 0) {
          throw new ApiError(422, INPUT_INVALID, '자기 자신이나 하위 단계를 상위로 지정할 수 없습니다.');
        }
      }
      const dup = await db.query(
        `SELECT sub_project_id AS "subProjectId" FROM sub_project
         WHERE project_id = CAST(:projectId AS bigint) AND sub_project_code = :code AND sub_project_id <> CAST(:subProjectId AS bigint)`,
        { projectId, code: f.code, subProjectId },
      );
      if (dup.length > 0) {
        throw new ApiError(422, INPUT_INVALID, '프로젝트 안에 같은 하위사업 코드가 있습니다.');
      }
      await checkEmployees(db, f.permitted);
      await db.execute(
        `UPDATE sub_project
         SET parent_sub_project_id = CAST(:parentId AS bigint), sub_project_code = :code, sub_project_name = :name,
             managing_account = :account, use_status = :useStatus, updated_at = now()
         WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
        { parentId: f.parentId, code: f.code, name: f.name, account: f.account, useStatus: f.useStatus, subProjectId },
      );
      if (f.permitted !== undefined) {
        await db.execute(
          `DELETE FROM project_permission WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
          { subProjectId },
        );
        await savePermissions(db, projectId, subProjectId, f.permitted);
      }
      return { subProjectId };
    });
  }

  @Delete('/sub-projects/:subProjectId')
  @HttpCode(200)
  async deleteSubProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const subProjectId = toId(req.params['subProjectId']);
    if (subProjectId === null) {
      throw new ApiError(404, 'SUB_PROJECT_NOT_FOUND', '하위사업을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT sub_project_id AS "subProjectId" FROM sub_project WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
        { subProjectId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SUB_PROJECT_NOT_FOUND', '하위사업을 찾을 수 없습니다.');
      }
      const children = await db.query(
        `SELECT COUNT(*) AS "count" FROM sub_project WHERE parent_sub_project_id = CAST(:subProjectId AS bigint)`,
        { subProjectId },
      );
      if (Number(children[0]['count']) > 0) {
        throw new ApiError(409, 'SUB_PROJECT_HAS_CHILDREN', '하위 단계가 있는 하위사업은 삭제할 수 없습니다.');
      }
      await db.execute(
        `DELETE FROM project_permission WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
        { subProjectId },
      );
      await db.execute(
        `DELETE FROM sub_project WHERE sub_project_id = CAST(:subProjectId AS bigint)`,
        { subProjectId },
      );
      return {};
    });
  }

  @Get('/sub-projects')
  async listSubProjects(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const projectId = toId(query['projectId']);
    if (projectId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 ID는 필수입니다.');
    }
    const pageNo = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeNo = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeNo) || sizeNo < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeNo, 200);
    return transaction(async (db) => {
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM sub_project WHERE project_id = CAST(:projectId AS bigint)`,
        { projectId },
      );
      const items = await db.query(
        `SELECT sub_project_id AS "subProjectId", parent_sub_project_id AS "parentSubProjectId",
                sub_project_code AS "subProjectCode", sub_project_name AS "subProjectName",
                managing_account AS "managingAccount", use_status AS "useStatus"
         FROM sub_project
         WHERE project_id = CAST(:projectId AS bigint)
         ORDER BY COALESCE(parent_sub_project_id, 0), sub_project_code
         LIMIT :size OFFSET :offset`,
        { projectId, size, offset: pageNo * size },
      );
      return { items, page: pageNo, size, total: Number(totals[0]['total']) };
    });
  }
}

interface Db {
  query(sql: string, params: Record<string, unknown>): Promise<Record<string, unknown>[]>;
  execute(sql: string, params: Record<string, unknown>): Promise<number>;
}

async function checkEmployees(db: Db, ids: number[] | undefined): Promise<void> {
  for (const employeeId of ids ?? []) {
    const rows = await db.query(
      `SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)`,
      { employeeId },
    );
    if (rows.length === 0) {
      throw new ApiError(422, INPUT_INVALID, '사용 권한 대상 임직원을 찾을 수 없습니다.');
    }
  }
}

async function savePermissions(db: Db, projectId: number, subProjectId: number, ids: number[] | undefined): Promise<void> {
  for (const employeeId of ids ?? []) {
    await db.execute(
      `INSERT INTO project_permission (project_id, sub_project_id, employee_id, created_at, updated_at)
       VALUES (CAST(:projectId AS bigint), CAST(:subProjectId AS bigint), CAST(:employeeId AS bigint), now(), now())`,
      { projectId, subProjectId, employeeId },
    );
  }
}

