import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field,
  TextInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];

interface FormState {
  parentSubProjectId: number | string;
  subProjectCode: string;
  subProjectName: string;
  managingAccount: string;
  useStatus: string;
  permitted: number[] | null;
}

const EMPTY: FormState = {
  parentSubProjectId: '',
  subProjectCode: '',
  subProjectName: '',
  managingAccount: '',
  useStatus: '사용',
  permitted: null,
};

export default function FnSfr00202Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [appliedProject, setAppliedProject] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'none' | 'create' | 'edit' | 'delete'>('none');
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<FormState>(EMPTY);
  const [empPick, setEmpPick] = useState<number | string>('');

  const list = useData<Page>(async () => {
    if (appliedProject === '') {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/sub-projects', role, undefined, { projectId: appliedProject, page: pageNo, size: 20 });
  }, [appliedProject, pageNo, role]);

  const rows = list.data?.items ?? [];
  const usedCount = rows.filter((r) => r['useStatus'] === '사용').length;

  function close() {
    setMode('none');
    setTarget(null);
    setEmpPick('');
  }

  function openCreate() {
    setForm({ ...EMPTY });
    setTarget(null);
    setMode('create');
  }

  function openEdit(row: Row) {
    setForm({
      parentSubProjectId: (row['parentSubProjectId'] as number | null) ?? '',
      subProjectCode: String(row['subProjectCode'] ?? ''),
      subProjectName: String(row['subProjectName'] ?? ''),
      managingAccount: String(row['managingAccount'] ?? ''),
      useStatus: String(row['useStatus'] ?? '사용'),
      permitted: null,
    });
    setTarget(row);
    setMode('edit');
  }

  function addEmployee() {
    if (empPick === '') {
      return;
    }
    const id = Number(empPick);
    const current = form.permitted ?? [];
    if (!current.includes(id)) {
      setForm({ ...form, permitted: [...current, id] });
    }
    setEmpPick('');
  }

  function removeEmployee(id: number) {
    setForm({ ...form, permitted: (form.permitted ?? []).filter((x) => x !== id) });
  }

  function checkRequired() {
    if (form.subProjectCode.trim() === '') {
      throw new Error('하위사업 코드를 입력해 주세요.');
    }
    if (form.subProjectName.trim() === '') {
      throw new Error('하위사업 명칭을 입력해 주세요.');
    }
    if (form.useStatus === '') {
      throw new Error('사용 여부를 선택해 주세요.');
    }
  }

  function body(): Row {
    const b: Row = {
      subProjectCode: form.subProjectCode.trim(),
      subProjectName: form.subProjectName.trim(),
      useStatus: form.useStatus,
    };
    if (form.parentSubProjectId !== '') {
      b['parentSubProjectId'] = form.parentSubProjectId;
    }
    if (form.managingAccount.trim() !== '') {
      b['managingAccount'] = form.managingAccount.trim();
    }
    if (form.permitted !== null) {
      b['permittedEmployeeIds'] = form.permitted;
    }
    return b;
  }

  async function submitCreate() {
    if (appliedProject === '') {
      throw new Error('프로젝트를 먼저 선택해 주세요.');
    }
    checkRequired();
    await call('POST', '/sub-projects', role, { ...body(), projectId: appliedProject });
    notify('하위사업을 등록했습니다.');
    close();
    list.reload();
  }

  async function submitEdit() {
    checkRequired();
    await call('PUT', '/sub-projects/' + String(target?.['subProjectId']), role, body());
    notify('하위사업을 수정했습니다.');
    close();
    list.reload();
  }

  async function submitDelete() {
    await call('DELETE', '/sub-projects/' + String(target?.['subProjectId']), role);
    notify('하위사업을 삭제했습니다.');
    close();
    list.reload();
  }

  const parentOptions: [string, string][] = rows
    .filter((r) => !target || r['subProjectId'] !== target['subProjectId'])
    .map((r) => [String(r['subProjectId']), String(r['subProjectCode']) + ' ' + String(r['subProjectName'])]);

  const fields = (
    <>
      <Field label="상위 하위사업 ID" hint="비우면 최상위 단계입니다.">
        <Select
          value={String(form.parentSubProjectId)}
          onChange={(v) => setForm({ ...form, parentSubProjectId: v === '' ? '' : Number(v) })}
          options={parentOptions}
          placeholder="최상위"
        />
      </Field>
      <Field label="하위사업 코드" required>
        <TextInput value={form.subProjectCode} onChange={(v) => setForm({ ...form, subProjectCode: v })} />
      </Field>
      <Field label="하위사업 명칭" required>
        <TextInput value={form.subProjectName} onChange={(v) => setForm({ ...form, subProjectName: v })} />
      </Field>
      <Field label="관리계좌">
        <TextInput value={form.managingAccount} onChange={(v) => setForm({ ...form, managingAccount: v })} />
      </Field>
      <Field label="사용 여부" required>
        <Select value={form.useStatus} onChange={(v) => setForm({ ...form, useStatus: v })} options={USE_OPTIONS} />
      </Field>
      <Field
        label="사용 권한 대상 임직원"
        wide
        hint={mode === 'edit' ? '변경하지 않으면 기존 권한을 그대로 둡니다. 추가하면 선택한 목록으로 바뀝니다.' : '지정한 임직원만 사용할 수 있습니다.'}
      >
        <LookupSelect table="employee" role={role} value={empPick} onChange={setEmpPick} placeholder="임직원 선택" />
        <button type="button" onClick={addEmployee}>추가</button>
        {(form.permitted ?? []).map((id) => (
          <span key={id}>
            <RefName table="employee" role={role} value={id} />
            <button type="button" onClick={() => removeEmployee(id)}>제거</button>
          </span>
        ))}
      </Field>
    </>
  );

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>프로젝트 선택</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setAppliedProject(projectId);
          }}
          onReset={() => {
            setProjectId('');
            setAppliedProject('');
            setPageNo(0);
          }}
        >
          <Field label="프로젝트 ID" required>
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} placeholder="프로젝트 선택" />
          </Field>
        </Filters>
      </section>
      <section className="box span-8">
        <h2>하위사업 현황</h2>
        <Tiles items={[['전체 하위사업', list.data?.total ?? 0], ['사용 중(현재 쪽)', usedCount]]} />
      </section>
      <section className="box span-12">
        <h2>하위사업 트리</h2>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate} disabled={appliedProject === ''}>하위사업 등록</button>
        </Band>
        {list.error !== '' && <ErrorText text={list.error} />}
        <DataTable
          rows={rows}
          empty={appliedProject === '' ? '프로젝트를 선택하고 조회해 주세요.' : '하위사업이 없습니다.'}
          columns={[
            { key: 'subProjectCode', label: '하위사업 코드' },
            { key: 'subProjectName', label: '하위사업 명칭' },
            {
              key: 'parentSubProjectId',
              label: '상위 하위사업 ID',
              render: (r) => (r['parentSubProjectId'] ? <RefName table="sub_project" role={role} value={r['parentSubProjectId']} /> : '최상위'),
            },
            { key: 'managingAccount', label: '관리계좌' },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
            {
              key: 'subProjectId',
              label: '처리',
              render: (r) => (
                <>
                  <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
                  <button type="button" onClick={(e) => { e.stopPropagation(); setTarget(r); setMode('delete'); }}>삭제</button>
                </>
              ),
            },
          ]}
        />
        <Pager page={pageNo} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPageNo} />
      </section>
      {mode === 'create' && (
        <Drawer title="하위사업 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="프로젝트 ID">
              <RefName table="project" role={role} value={appliedProject} />
            </Field>
            {fields}
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && target && (
        <Drawer title="하위사업 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="수정">
            {fields}
          </Form>
        </Drawer>
      )}
      {mode === 'delete' && target && (
        <Drawer title="하위사업 삭제" onClose={close}>
          <Pairs
            items={[
              ['하위사업 코드', String(target['subProjectCode'])],
              ['하위사업 명칭', String(target['subProjectName'])],
              ['사용 여부', <Badge key="s" value={target['useStatus']} />],
            ]}
          />
          <Form onSubmit={submitDelete} submit="삭제" danger note="하위 단계가 있는 하위사업은 삭제할 수 없습니다." />
        </Drawer>
      )}
    </div>
  );
}
